item.command:
/bin/bash -lc "python3 - <<'PY'
import json,pathlib
for f in sorted(pathlib.Path('results_m2/out/records').glob('*.json')):
 d=json.loads(f.read_text());v=d.get('values',{});v={k:x for k,x in v.items() if k not in ['labels']}
 if d['cell']['kind'] in ['endpoint','arm'] or any(s in f.name for s in ['dispersion','I1_','residual_sweep']):
  print(str(f),json.dumps({'decision':d['decision'],'rule':d['decision_rule'],'values':v},separators=(',',':')))
PY"

